'use strict';
/* FlowBank is a local-only simulation. It never sends money or authenticates real users. */
const STORE='flowbank-demo-v4';
const LEGACY_STORE='flowbank-demo-v3';
const SECOND_STORE='flowbank-demo-v2';
const FIRST_STORE='flowbank-demo-v1';
const CATEGORIES=['Compras','Mercado','Alimentação','Transporte','Serviços','Lazer','Saúde','Moradia','Contas','Outros'];
let planningTab='budgets',calendarOffset=0;
const BANKS=['FlowBank','Aurora Digital','Nexo Bank','Orbe Finance','Atlas Digital','Lume Bank','Horizonte','Vento Bank','Brisa Finance','Nova Conta'];
let chartPeriod=6;
const $=id=>document.getElementById(id);
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'fb-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value)||0);
const dateText=value=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value));
const shortDate=value=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(value));
const safeNumber=value=>{const n=Number(value);return Number.isFinite(n)?Math.round(n*100)/100:NaN};
const validAmount=value=>Number.isFinite(value)&&value>0&&value<=1000000;
const monthKey=date=>{let d=new Date(date);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')};
function makeTx(amount,description,category,method,daysAgo=0){let date=new Date();date.setDate(date.getDate()-daysAgo);return{id:uid(),amount,description,category,method,date:date.toISOString(),counterparty:''}}
function seedData(){
 const initial=[
  makeTx(2200,'Pagamento de projeto','Receitas','Recebimento',7),
  makeTx(-480,'Assinaturas e serviços','Serviços','Cartão',5),
  makeTx(-1200,'Aluguel do estúdio','Moradia','Transferência',10),
  makeTx(-170,'Mercado do bairro','Compras','Cartão',2),
  makeTx(1750,'Projeto criativo','Receitas','Recebimento',36),
  makeTx(-610,'Compras do mês','Compras','Cartão',42),
  makeTx(-245,'Contas de casa','Contas','Boleto',68),
  makeTx(1300,'Pagamento recebido','Receitas','Pix',75),
  makeTx(-380,'Assinaturas','Serviços','Cartão',101),
  makeTx(980,'Projeto independente','Receitas','Recebimento',133),
  makeTx(-320,'Compras','Compras','Cartão',149)
 ];
 return{version:1,theme:'dark',activeId:null,accounts:[
  {id:'demo-alex',name:'Alex Demo',handle:'alex.flow',bank:'FlowBank',demoRecipient:true,pix:'alex@flow.test',balance:12850,card:{blocked:false,limit:5000,used:1280,color:'#2762af'},goals:[{id:'g1',name:'Viagem dos sonhos',target:8000,saved:2800,icon:'✈'},{id:'g2',name:'Reserva criativa',target:12000,saved:4650,icon:'✦'}],transactions:initial,notifications:[{id:uid(),text:'Seu painel demonstrativo está pronto.',date:new Date().toISOString(),read:false}]},
  {id:'demo-maria',name:'Marina Demo',handle:'marina.flow',bank:'Aurora Digital',demoRecipient:true,pix:'marina@flow.test',balance:6200,card:{blocked:false,limit:3000,used:320,color:'#8e4eb7'},goals:[],transactions:[],notifications:[]},
  {id:'demo-rafael',name:'Rafael Demo',handle:'rafael.flow',bank:'Nexo Bank',demoRecipient:true,pix:'rafael@flow.test',balance:8350,card:{blocked:false,limit:3500,used:730,color:'#28847d'},goals:[],transactions:[],notifications:[]}
 ]};
}
function normalizeData(model){model.accounts.forEach(a=>{a.bank=BANKS.includes(a.bank)?a.bank:'FlowBank';a.demoRecipient=!!a.demoRecipient;a.transactions=Array.isArray(a.transactions)?a.transactions:[];if(!Array.isArray(a.cards)||!a.cards.length){let old=a.card||{};a.cards=[{id:'card-'+a.id,bank:a.bank,limit:Number(old.limit)||3000,blocked:!!old.blocked,color:/^#[0-9a-f]{6}$/i.test(old.color||'')?old.color:'#2762af',last4:'2048'}]}a.cards=a.cards.filter(c=>c&&c.id).map(c=>({id:String(c.id),bank:String(c.bank||a.bank),limit:Number(c.limit)||3000,blocked:!!c.blocked,color:/^#[0-9a-f]{6}$/i.test(c.color||'')?c.color:'#2762af',last4:/^\d{4}$/.test(String(c.last4||''))?String(c.last4):'2048',closingDay:Number(c.closingDay)||5,dueDay:Number(c.dueDay)||12}));a.budgets=Array.isArray(a.budgets)?a.budgets:[];a.recurring=Array.isArray(a.recurring)?a.recurring:[];let first=a.cards[0];a.transactions.forEach(t=>{if(t.method==='Cartão'&&!t.cardId)t.cardId=first.id;if(t.method==='Cartão'&&!t.billingMode)t.billingMode='paid-direct'});delete a.card});return model}
function load(){try{let parsed=JSON.parse(localStorage.getItem(STORE)||localStorage.getItem(LEGACY_STORE)||localStorage.getItem(SECOND_STORE)||localStorage.getItem(FIRST_STORE));if(parsed&&Array.isArray(parsed.accounts)&&parsed.accounts.length)return normalizeData(parsed)}catch{}return normalizeData(seedData())}
let data=load(),view='dashboard',txFilter='all',txSearch='',txMonth='all',txCard='all',toastTimer=null,unlockedId=null;
const HASH_ITERATIONS=600000;
function save(){try{localStorage.setItem(STORE,JSON.stringify(data))}catch{toast('Não foi possível salvar neste navegador.')}}
function account(){return data.accounts.find(a=>a.id===data.activeId)}
function others(){return data.accounts.filter(a=>a.id!==data.activeId)}
function notify(a,text){a.notifications.unshift({id:uid(),text,date:new Date().toISOString(),read:false});a.notifications=a.notifications.slice(0,40)}
function cashDelta(t){return Number.isFinite(t.cashDelta)?t.cashDelta:t.amount}
function post(a,tx){let before=categorySpend(a,tx.category,monthKey(new Date()));a.balance=safeNumber(a.balance+cashDelta(tx));a.transactions.unshift({...tx,id:uid(),date:new Date().toISOString()});notify(a,cashDelta(tx)>=0?'Entrada de '+money(cashDelta(tx))+': '+tx.description:'Saída de '+money(Math.abs(cashDelta(tx)))+': '+tx.description);if(tx.amount<0&&tx.method!=='Fatura'&&tx.category!=='Meta')checkBudget(a,tx.category,before,categorySpend(a,tx.category,monthKey(new Date())))}
function commit(){save();render();updateNotificationCount()}
function toast(message){let el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function cryptoReady(){return !!(globalThis.crypto&&crypto.subtle&&crypto.getRandomValues)}
function base64(bytes){return btoa(String.fromCharCode(...bytes))}
function unbase64(value){return Uint8Array.from(atob(value),c=>c.charCodeAt(0))}
async function passwordBits(password,salt,iterations){let material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt,iterations},material,256))}
async function setPassword(a,password){let salt=crypto.getRandomValues(new Uint8Array(16)),hash=await passwordBits(password,salt,HASH_ITERATIONS);a.auth={algorithm:'PBKDF2-SHA256',iterations:HASH_ITERATIONS,salt:base64(salt),hash:base64(hash)}}
async function verifyPassword(a,password){try{let auth=a.auth;if(!auth||auth.algorithm!=='PBKDF2-SHA256'||auth.iterations<100000||auth.iterations>1000000)return false;let expected=unbase64(auth.hash),actual=await passwordBits(password,unbase64(auth.salt),auth.iterations);if(expected.length!==actual.length)return false;let diff=0;for(let i=0;i<expected.length;i++)diff|=expected[i]^actual[i];return diff===0}catch{return false}}
function passwordValid(password,confirmation){if(password.length<12||password.length>128){toast('Use uma senha local de 12 a 128 caracteres.');return false}if(password!==confirmation){toast('As senhas digitadas não coincidem.');return false}return true}
function showAuth(){let logged=!!account()&&unlockedId===data.activeId;$('auth-screen').hidden=logged;$('app').hidden=!logged;if(logged){render();return}renderProfiles();setAuthTab(data.accounts.some(a=>!a.demoRecipient)?'login':'register')}
function renderProfiles(){const users=data.accounts.filter(a=>!a.demoRecipient);$('login-profile').innerHTML=users.length?users.map(a=>'<option value="'+escapeHtml(a.id)+'">'+escapeHtml(a.name)+' · '+escapeHtml(a.bank)+'</option>').join(''):'<option value="">Crie seu usuário primeiro</option>';if(users.some(a=>a.id===data.activeId))$('login-profile').value=data.activeId;$('register-bank').innerHTML=BANKS.map(bank=>'<option value="'+escapeHtml(bank)+'">'+escapeHtml(bank)+'</option>').join('');syncLoginPasswordMode()}
function syncLoginPasswordMode(){let a=data.accounts.find(a=>a.id===$('login-profile').value),setup=!!a&&!a.auth;$('login-confirm-field').hidden=!setup;$('login-confirm').required=setup;$('login-password').autocomplete=setup?'new-password':'current-password';$('login-password-hint').textContent=setup?'Este perfil antigo ainda não tinha senha. Defina uma senha local para continuar.':'Digite a senha local criada para este perfil.';$('login-submit').innerHTML=setup?'Definir senha e entrar <span>→</span>':'Entrar no painel <span>→</span>'}
function setAuthTab(tab){$('login-password').value='';$('login-confirm').value='';$('register-password').value='';$('register-confirm').value='';let login=tab==='login';$('login-form').hidden=!login;$('register-form').hidden=login;$('login-tab').classList.toggle('active',login);$('register-tab').classList.toggle('active',!login);$('auth-title').textContent=login?'Entre na demonstração.':'Crie um perfil fictício.';if(login)syncLoginPasswordMode()}
async function login(id,password,confirmation){let a=data.accounts.find(a=>a.id===id&&!a.demoRecipient);if(!a)return toast('Crie ou selecione seu usuário fictício.');if(!cryptoReady())return toast('Abra o FlowBank em HTTPS para usar a senha local.');if(a.auth){if(!await verifyPassword(a,password))return toast('Senha incorreta. Confira e tente novamente.')}else{if(!passwordValid(password,confirmation))return;await setPassword(a,password)}$('login-password').value='';$('login-confirm').value='';data.activeId=id;unlockedId=id;view='dashboard';save();showAuth();toast('Bem-vindo ao FlowBank demo')}
function logout(){unlockedId=null;data.activeId=null;save();$('popover-root').innerHTML='';closeModal();$('login-password').value='';$('login-confirm').value='';showAuth()}
async function register(name,handle,bank,password,confirmation){name=name.trim();handle=handle.trim().toLowerCase();if(!BANKS.includes(bank))return toast('Escolha um banco da demonstração.');if(name.length<2||!indexHandle(handle))return toast('Confira o nome e o identificador.');if(data.accounts.some(a=>a.handle===handle))return toast('Esse identificador já está em uso.');if(!passwordValid(password,confirmation))return;if(!cryptoReady())return toast('Abra o FlowBank em HTTPS para criar uma senha local.');let a={id:uid(),name,handle,bank,demoRecipient:false,pix:handle+'@flow.test',balance:3500,cards:[{id:uid(),bank,blocked:false,limit:2000,color:'#2762af',last4:String(Math.floor(1000+Math.random()*9000)),closingDay:5,dueDay:12}],goals:[],budgets:[],recurring:[],transactions:[],notifications:[]};await setPassword(a,password);$('register-password').value='';$('register-confirm').value='';data.accounts.push(a);data.activeId=a.id;unlockedId=a.id;save();showAuth();toast('Usuário fictício criado')}
function indexHandle(h){return /^[a-z0-9._-]{3,20}$/.test(h)}
function pageHeader(kicker,title,sub,actions=''){return '<div class="page-header"><div><p class="eyebrow">'+kicker+'</p><h1>'+title+'</h1><p>'+sub+'</p></div>'+actions+'</div>'}
function panelHead(title,action,label){return '<div class="panel-head"><h2>'+title+'</h2>'+(action?'<button class="quiet-button" data-action="'+action+'">'+label+'</button>':'')+'</div>'}
function filteredTransactions(){let a=account();return a.transactions.filter(t=>{if(txFilter!=='all'&&(txFilter==='credit'?t.amount<0:t.amount>=0))return false;if(txMonth!=='all'&&monthKey(t.date)!==txMonth)return false;if(txCard!=='all'&&t.cardId!==txCard)return false;let q=txSearch.toLocaleLowerCase('pt-BR');return !q||[t.description,t.category,t.method,t.counterparty].some(s=>String(s||'').toLocaleLowerCase('pt-BR').includes(q))}).sort((x,y)=>new Date(y.date)-new Date(x.date))}
function txRows(list){if(!list.length)return '<tr><td colspan="4"><div class="empty-state"><strong>Sem movimentações</strong>Nenhum item encontrado para este filtro.</div></td></tr>';return list.map(t=>'<tr><td><div class="transaction-main"><span class="transaction-icon '+(t.amount>=0?'credit':'')+'">'+(t.amount>=0?'↙':t.method==='Boleto'?'▤':'↗')+'</span><span><strong>'+escapeHtml(t.description)+'</strong><small>'+dateText(t.date)+' · '+escapeHtml(t.method)+(t.cardId?' · '+escapeHtml(account().cards.find(c=>c.id===t.cardId)?.bank||'Cartão'):'')+(t.installments?' · '+t.installmentIndex+'/'+t.installments:'')+(t.note?' · '+escapeHtml(t.note):'')+'</small></span></div></td><td>'+escapeHtml(t.category)+'</td><td><span class="transaction-tag '+(t.amount<0?'debit':'')+'">'+(t.billingMode==='invoice'?(t.paidAt?'Fatura paga':'Na fatura'):t.amount>=0?'Entrada':'Concluído')+'</span><button class="tx-edit quiet-button" data-action="edit-tx" data-id="'+escapeHtml(t.id)+'" aria-label="Editar categoria e nota">Editar</button></td><td class="amount '+(t.amount>=0?'credit':'debit')+'">'+(t.amount>=0?'+':'−')+money(Math.abs(t.amount))+'</td></tr>').join('')}
function txTable(list){return '<div class="table-wrap"><table class="transaction-table"><thead><tr><th>Movimentação</th><th>Categoria</th><th>Status</th><th style="text-align:right">Valor</th></tr></thead><tbody id="transaction-rows">'+txRows(list)+'</tbody></table></div>'}
function months(count=chartPeriod){let out=[];let now=new Date();for(let i=count-1;i>=0;i--){let d=new Date(now.getFullYear(),now.getMonth()-i,1);out.push({key:monthKey(d),label:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(d).replace('.',''),income:0,expense:0})}for(let t of account().transactions){let m=out.find(x=>x.key===monthKey(t.date));if(m){let delta=cashDelta(t);if(delta>=0)m.income+=delta;else m.expense+=Math.abs(delta)}}return out}
function chartSvg(series){let width=560,height=128,pad=14,max=Math.max(100,...series.flatMap(x=>[x.income,x.expense]))*1.12;const point=(value,i)=>[pad+i*(width-2*pad)/(series.length-1),height-10-value/max*(height-22)];const path=key=>series.map((m,i)=>{let p=point(m[key],i);return(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)}).join(' ');let lines=[0,.25,.5,.75,1].map(f=>'<line x1="0" x2="560" y1="'+(height-10-f*(height-22))+'" y2="'+(height-10-f*(height-22))+'" stroke="var(--stroke)" stroke-width=".7"/>').join('');return '<svg viewBox="0 0 560 128" preserveAspectRatio="none" role="img" aria-label="Gráfico de receitas e despesas dos últimos seis meses"><defs><linearGradient id="incomeShade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#5ce1ba" stop-opacity=".25"/><stop offset="1" stop-color="#5ce1ba" stop-opacity="0"/></linearGradient></defs>'+lines+'<path d="'+path('income')+' L546 128 L14 128 Z" fill="url(#incomeShade)"/><path d="'+path('expense')+'" fill="none" stroke="#648fcf" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="'+path('income')+'" fill="none" stroke="#70e5c1" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
function categoryData(){let totals={};for(let t of account().transactions){if(t.amount<0&&t.category!=='Meta'&&t.method!=='Fatura'){totals[t.category]=(totals[t.category]||0)+Math.abs(t.amount)}}return Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,4)}
function categoryHtml(){let list=categoryData(),total=list.reduce((s,x)=>s+x[1],0)||1,colors=['#6cbbef','#85dec3','#b0a8f1','#ead584'];if(!list.length)return '<div class="empty-state">Suas despesas aparecerão aqui.</div>';return '<div class="category-list">'+list.map(([name,value],i)=>'<div class="category-row"><div class="category-row-top"><span>'+escapeHtml(name)+'</span><strong>'+money(value)+'</strong></div><div class="category-track"><i style="width:'+Math.round(value/total*100)+'%;background:'+colors[i]+'"></i></div></div>').join('')+'</div>'}
function cardInk(color){let c=color.replace('#',''),r=parseInt(c.slice(0,2),16),g=parseInt(c.slice(2,4),16),b=parseInt(c.slice(4,6),16);return (r*.299+g*.587+b*.114)>170?'#102139':'#f7fbff'}
function addMonthsKey(key,offset){let [year,month]=key.split('-').map(Number),date=new Date(year,month-1+offset,1);return monthKey(date)}
function invoiceKeyFor(date,closingDay){let d=new Date(date),key=monthKey(d);return d.getDate()>closingDay?addMonthsKey(key,1):key}
function invoiceDueDate(card,key){let [year,month]=key.split('-').map(Number),shift=card.dueDay<=card.closingDay?1:0;return new Date(year,month-1+shift,card.dueDay,12)}
function cardOutstanding(a,id){return a.transactions.filter(t=>t.cardId===id&&t.method==='Cartão'&&t.billingMode==='invoice'&&!t.paidAt).reduce((sum,t)=>sum+Math.abs(t.amount),0)}
function invoiceGroups(a,card){let map=new Map();for(let t of a.transactions){if(t.cardId!==card.id||t.billingMode!=='invoice')continue;let key=t.invoiceKey||invoiceKeyFor(t.date,card.closingDay),group=map.get(key)||{key,items:[],total:0,unpaid:0};group.items.push(t);group.total+=Math.abs(t.amount);if(!t.paidAt)group.unpaid+=Math.abs(t.amount);map.set(key,group)}return [...map.values()].sort((x,y)=>x.key.localeCompare(y.key))}
function currencyParts(value){let parts=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).formatToParts(value);return parts.map(p=>p.value).join('')}
function expenseTransactions(a,key){return a.transactions.filter(t=>t.amount<0&&t.method!=='Fatura'&&t.category!=='Meta'&&monthKey(t.date)===key)}
function categorySpend(a,category,key){return expenseTransactions(a,key).filter(t=>t.category===category).reduce((sum,t)=>sum+Math.abs(t.amount),0)}
function checkBudget(a,category,before,after){let budget=a.budgets.find(b=>b.category===category);if(!budget||!Number.isFinite(budget.limit)||budget.limit<=0)return;let from=before/budget.limit,to=after/budget.limit;if(from<1&&to>=1)notify(a,'Orçamento de '+category+' ultrapassado: '+money(after)+' de '+money(budget.limit));else if(from<.8&&to>=.8)notify(a,'Atenção: '+category+' atingiu 80% do orçamento.')}
function cardSpent(a,id,key=monthKey(new Date())){return a.transactions.filter(t=>t.method==='Cartão'&&t.cardId===id&&t.amount<0&&monthKey(t.date)===key).reduce((sum,t)=>sum-Math.abs(t.amount),0)*-1}
function allCardSpent(a,key=monthKey(new Date())){return a.cards.reduce((sum,c)=>sum+cardSpent(a,c.id,key),0)}
function cardFace(a,c){let color=/^#[0-9a-f]{6}$/i.test(c.color)?c.color:'#2762af';return '<div class="virtual-card" style="--card-color:'+color+';--card-ink:'+cardInk(color)+'"><div class="card-logo-row"><span class="card-brand">flow<span>bank</span></span><span class="master-symbol"><i></i><i></i></span></div><span class="card-chip" aria-hidden="true"></span><div class="card-number">•••• •••• •••• '+escapeHtml(c.last4)+'</div><div class="card-bottom"><span>'+escapeHtml(a.name)+'</span><span>'+escapeHtml(c.bank)+' · DEMO</span></div></div>'}
function cardTile(a,c){let spent=cardSpent(a,c.id),outstanding=cardOutstanding(a,c.id),pct=Math.min(100,Math.round(outstanding/c.limit*100));return '<article class="panel card-tile">'+cardFace(a,c)+'<div class="card-tile-meta"><div><strong>'+escapeHtml(c.bank)+'</strong><span>Final '+escapeHtml(c.last4)+' · '+(c.blocked?'Bloqueado':'Ativo')+'</span></div><span class="card-tile-spent">'+money(spent)+'</span></div><div class="limit-meter"><i style="width:'+pct+'%"></i></div><div class="limit-labels"><span>Fatura em aberto: '+money(outstanding)+'</span><span>Limite livre: '+money(Math.max(0,c.limit-outstanding))+'</span></div><div class="card-cycle">Fecha dia '+c.closingDay+' · Vence dia '+c.dueDay+'</div><div class="card-tile-actions"><button class="primary-button" data-action="card-expense" data-id="'+escapeHtml(c.id)+'" '+(c.blocked?'disabled title="Desbloqueie o cartão"':'')+'>＋ Nova compra</button><button class="secondary-button" data-action="card-invoices" data-id="'+escapeHtml(c.id)+'">Faturas</button><button class="secondary-button" data-action="card-color" data-id="'+escapeHtml(c.id)+'">Cor</button><button class="secondary-button" data-action="limit" data-id="'+escapeHtml(c.id)+'">Limite</button><button class="secondary-button" data-action="card-settings" data-id="'+escapeHtml(c.id)+'">Datas</button><button class="secondary-button" data-action="toggle-card" data-id="'+escapeHtml(c.id)+'" aria-pressed="'+c.blocked+'">'+(c.blocked?'Desbloquear':'Bloquear')+'</button></div></article>'}
function dashboard(){let a=account(),m=months(),current=m[m.length-1],unread=a.notifications.filter(n=>!n.read).length;return pageHeader('SEU FLUXO CONTINUA','Olá, '+escapeHtml(a.name.split(' ')[0])+'.','Veja seu dinheiro fictício em movimento.','<div class="header-actions"><button class="secondary-button" data-action="statement">Ver extrato</button><button class="primary-button" data-action="pix">Fazer Pix <span>↗</span></button></div>')+'<div class="dashboard-grid"><section class="panel balance-panel"><div class="balance-top"><div><span class="balance-caption">Saldo disponível</span><div class="balance-amount">'+money(a.balance)+'</div></div><div class="balance-actions">'+[3,6,12].map(n=>'<button class="period-button '+(chartPeriod===n?'active':'')+'" data-period="'+n+'" aria-pressed="'+(chartPeriod===n)+'">'+n+' meses</button>').join('')+'</div></div><div class="balance-chart">'+chartSvg(m)+'</div><div class="month-labels">'+m.map(x=>'<span>'+x.label+'</span>').join('')+'</div><div class="balance-footer"><div class="balance-summary"><span>Entradas <strong>'+money(current.income)+'</strong></span><span>Saídas <strong>'+money(current.expense)+'</strong></span></div><div class="legend"><span><i class="income"></i> Receitas</span><span><i class="expense"></i> Despesas</span></div></div></section><section class="panel card-panel">'+panelHead('Seus cartões','cards','Ver todos')+cardFace(a,a.cards[0])+'<div class="card-meta"><span>'+a.cards.length+' cartão'+(a.cards.length===1?'':'ões')+' · gasto do mês<br><strong>'+money(allCardSpent(a))+'</strong></span><button class="quiet-button" data-action="card-expense" data-id="'+escapeHtml(a.cards[0].id)+'">Nova compra ＋</button></div></section><section class="panel quick-panel">'+panelHead('Acesso rápido')+'<div class="quick-actions"><button class="quick-action" data-action="transfer"><span class="quick-icon">↗</span> Transferir</button><button class="quick-action" data-action="pix"><span class="quick-icon">✳</span> Fazer Pix</button><button class="quick-action" data-action="boleto"><span class="quick-icon">▤</span> Pagar boleto</button><button class="quick-action" data-action="receive"><span class="quick-icon">↙</span> Receber demo</button></div></section><section class="panel transactions-panel">'+panelHead('Movimentações recentes','statement','Ver todas')+txTable(a.transactions.slice(0,5))+'</section><section class="panel insights-panel">'+panelHead('Onde você gastou','statement','Ver extrato')+categoryHtml()+'<div class="insight-banner"><strong>Seu dinheiro tem direção.</strong><p>Crie uma meta e acompanhe cada passo.</p><button data-view="goals">Explorar metas</button></div></section></div>'}
function transactionsPage(){let a=account(),credit=a.transactions.filter(t=>cashDelta(t)>0).reduce((s,t)=>s+cashDelta(t),0),debit=a.transactions.filter(t=>cashDelta(t)<0).reduce((s,t)=>s-cashDelta(t),0);let options=[...new Set(a.transactions.map(t=>monthKey(t.date)))].sort().reverse();return pageHeader('CADA MOVIMENTO CONTA','Extrato completo.','Todas as operações desta simulação ficam registradas aqui.')+'<div class="metric-row"><div class="panel metric-card"><span>Saldo atual</span><strong>'+money(a.balance)+'</strong><small>Disponível para simulações</small></div><div class="panel metric-card"><span>Total recebido</span><strong>'+money(credit)+'</strong><small>Movimentações registradas</small></div><div class="panel metric-card"><span>Total de saídas</span><strong>'+money(debit)+'</strong><small>Inclui reservas para metas</small></div></div><section class="panel panel-pad">'+panelHead('Movimentações')+'<div class="filter-row"><input id="tx-search" type="search" placeholder="Buscar movimentação..." value="'+escapeHtml(txSearch)+'" aria-label="Buscar movimentação"><select id="tx-type" aria-label="Tipo de movimentação"><option value="all" '+(txFilter==='all'?'selected':'')+'>Todos os tipos</option><option value="credit" '+(txFilter==='credit'?'selected':'')+'>Entradas</option><option value="debit" '+(txFilter==='debit'?'selected':'')+'>Saídas</option></select><select id="tx-card" aria-label="Cartão"><option value="all">Todos os cartões</option>'+a.cards.map(c=>'<option value="'+escapeHtml(c.id)+'" '+(txCard===c.id?'selected':'')+'>'+escapeHtml(c.bank)+' · '+escapeHtml(c.last4)+'</option>').join('')+'</select><select id="tx-month" aria-label="Mês"><option value="all">Todos os meses</option>'+options.map(k=>'<option value="'+k+'" '+(txMonth===k?'selected':'')+'>'+new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(k+'-01T12:00:00'))+'</option>').join('')+'</select></div>'+txTable(filteredTransactions())+'</section>'}
function cardCategories(a){let map={};for(let t of a.transactions){if(t.method==='Cartão'&&t.amount<0&&monthKey(t.date)===monthKey(new Date()))map[t.category]=(map[t.category]||0)+Math.abs(t.amount)}return Object.entries(map).sort((x,y)=>y[1]-x[1])}
function cardInsights(a){let categories=cardCategories(a),total=allCardSpent(a),colors=['#6cbbef','#85dec3','#b0a8f1','#ead584','#f28caa'];return '<section class="panel panel-pad"><div class="panel-head"><h2>Gastos por categoria neste mês</h2></div>'+(categories.length?'<div class="category-list">'+categories.map(([name,value],i)=>'<div class="category-row"><div class="category-row-top"><span>'+escapeHtml(name)+'</span><strong>'+money(value)+'</strong></div><div class="category-track"><i style="width:'+Math.round(value/Math.max(1,total)*100)+'%;background:'+colors[i%colors.length]+'"></i></div></div>').join('')+'</div>':'<div class="empty-state">Registre um gasto para acompanhar as categorias.</div>')+'</section>'}
function invoiceList(a){let rows=a.cards.flatMap(c=>invoiceGroups(a,c).map(g=>({card:c,...g}))).sort((x,y)=>invoiceDueDate(x.card,x.key)-invoiceDueDate(y.card,y.key));if(!rows.length)return '<div class="empty-state">As compras novas aparecerão aqui em faturas.</div>';return '<div class="invoice-list">'+rows.slice(0,12).map(g=>'<div class="invoice-row"><div><strong>'+escapeHtml(g.card.bank)+' · final '+escapeHtml(g.card.last4)+'</strong><span>Vence '+dateText(invoiceDueDate(g.card,g.key))+' · '+g.items.length+' parcela(s)</span></div><div class="invoice-row-amount"><strong>'+money(g.total)+'</strong><span>'+(g.unpaid>0?'Em aberto: '+money(g.unpaid):'Paga')+'</span></div>'+(g.unpaid>0?'<button class="secondary-button" data-action="pay-invoice" data-id="'+escapeHtml(g.card.id)+'" data-key="'+g.key+'">Pagar</button>':'')+'</div>').join('')+'</div>'}
function cardsPage(){let a=account(),spent=allCardSpent(a),outstanding=a.cards.reduce((sum,c)=>sum+cardOutstanding(a,c.id),0),available=a.cards.reduce((sum,c)=>sum+Math.max(0,c.limit-cardOutstanding(a,c.id)),0),cardTx=a.transactions.filter(t=>t.method==='Cartão').slice(0,8);return pageHeader('SEUS GASTOS, CARTÃO POR CARTÃO','Meus cartões.','Acompanhe compras, parcelas, faturas e limites por banco.','<button class="primary-button" data-action="add-card">＋ Adicionar cartão</button>')+'<div class="metric-row"><div class="panel metric-card"><span>Compras neste mês</span><strong>'+money(spent)+'</strong><small>Registradas em todos os cartões</small></div><div class="panel metric-card"><span>Faturas em aberto</span><strong>'+money(outstanding)+'</strong><small>Parcelas ainda não pagas</small></div><div class="panel metric-card"><span>Limite disponível</span><strong>'+money(available)+'</strong><small>Somatório dos cartões</small></div></div><div class="card-collection">'+a.cards.map(c=>cardTile(a,c)).join('')+'</div><section class="panel panel-pad" id="invoice-section">'+panelHead('Faturas dos cartões')+invoiceList(a)+'</section><div class="card-monitor-grid">'+cardInsights(a)+'<section class="panel panel-pad">'+panelHead('Últimas compras','statement','Ver extrato')+txTable(cardTx)+'</section></div><div class="callout" style="margin-top:16px">Uma compra fictícia ocupa o limite do cartão. O saldo disponível é descontado somente quando a fatura é paga.</div>'}
function goalCards(){let a=account();if(!a.goals.length)return '<div class="panel empty-state"><strong>Nenhuma meta ainda</strong>Crie sua primeira meta financeira fictícia.</div>';return '<div class="goal-grid">'+a.goals.map(g=>{let percent=Math.min(100,Math.round(g.saved/g.target*100));return '<article class="panel goal-card"><div class="goal-card-top"><span class="goal-icon">'+escapeHtml(g.icon||'◎')+'</span><button class="quiet-button" data-action="goal-menu" data-id="'+escapeHtml(g.id)+'" title="Retirar valor da meta">Retirar</button></div><h3>'+escapeHtml(g.name)+'</h3><p>'+percent+'% concluída</p><div class="goal-amount">'+money(g.saved)+' <small>de '+money(g.target)+'</small></div><div class="goal-progress"><i style="width:'+percent+'%"></i></div><div class="goal-footer"><span>'+money(Math.max(0,g.target-g.saved))+' para chegar lá</span><button class="quiet-button" data-action="add-goal-funds" data-id="'+escapeHtml(g.id)+'">Adicionar ＋</button></div></article>'}).join('')+'</div>'}
function planningTabs(){return '<div class="planning-tabs">'+[['budgets','Orçamentos'],['recurring','Recorrências'],['calendar','Calendário'],['goals','Metas']].map(([id,label])=>'<button class="'+(planningTab===id?'active':'')+'" data-planning-tab="'+id+'">'+label+'</button>').join('')+'</div>'}
function budgetsView(){let a=account(),key=monthKey(new Date()),prior=addMonthsKey(key,-1),thisSpend=expenseTransactions(a,key).reduce((s,t)=>s+Math.abs(t.amount),0),lastSpend=expenseTransactions(a,prior).reduce((s,t)=>s+Math.abs(t.amount),0),delta=lastSpend?Math.round((thisSpend/lastSpend-1)*100):null;return '<div class="metric-row"><div class="panel metric-card"><span>Despesas neste mês</span><strong>'+money(thisSpend)+'</strong><small>Inclui compras no cartão</small></div><div class="panel metric-card"><span>Mês anterior</span><strong>'+money(lastSpend)+'</strong><small>'+new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(new Date(prior+'-01T12:00:00'))+'</small></div><div class="panel metric-card"><span>Variação mensal</span><strong>'+(delta===null?'—':(delta>0?'+':'')+delta+'%')+'</strong><small>Comparação de despesas</small></div></div><section class="panel panel-pad"><div class="panel-head"><h2>Limites por categoria</h2><button class="secondary-button" data-action="budget-edit">＋ Definir orçamento</button></div>'+(a.budgets.length?'<div class="budget-list">'+a.budgets.map(b=>{let spent=categorySpend(a,b.category,key),pct=Math.round(spent/b.limit*100);return '<div class="budget-row"><div class="category-row-top"><strong>'+escapeHtml(b.category)+'</strong><span>'+money(spent)+' de '+money(b.limit)+'</span></div><div class="category-track"><i class="'+(pct>=100?'danger':pct>=80?'warning':'')+'" style="width:'+Math.min(100,pct)+'%"></i></div><small>'+pct+'% usado</small><button class="quiet-button" data-action="budget-edit" data-id="'+escapeHtml(b.category)+'">Editar</button><button class="quiet-button" data-action="budget-remove" data-id="'+escapeHtml(b.category)+'">Remover</button></div>'}).join('')+'</div>':'<div class="empty-state">Defina um orçamento para receber alertas em 80% e 100%.</div>')+'</section>'}
function recurringView(){let a=account(),key=monthKey(new Date());return '<section class="panel panel-pad"><div class="panel-head"><h2>Contas e assinaturas</h2><button class="secondary-button" data-action="recurring-edit">＋ Adicionar</button></div><p class="field-hint">Lembretes não debitam seu saldo. Registre o pagamento quando ele acontecer na simulação.</p>'+(a.recurring.length?'<div class="recurring-list">'+a.recurring.map(r=>'<div class="recurring-row"><div><strong>'+escapeHtml(r.name)+'</strong><span>'+escapeHtml(r.category)+' · dia '+r.dueDay+' · '+(r.active?'Ativa':'Pausada')+'</span></div><strong>'+money(r.amount)+'</strong><div class="row-actions"><button class="quiet-button" data-action="recurring-pay" data-id="'+escapeHtml(r.id)+'" '+(!r.active||r.lastPaidKey===key?'disabled':'')+'>'+(r.lastPaidKey===key?'Pago':'Pagar')+'</button><button class="quiet-button" data-action="recurring-edit" data-id="'+escapeHtml(r.id)+'">Editar</button><button class="quiet-button" data-action="recurring-toggle" data-id="'+escapeHtml(r.id)+'">'+(r.active?'Pausar':'Ativar')+'</button><button class="quiet-button" data-action="recurring-remove" data-id="'+escapeHtml(r.id)+'">Remover</button></div></div>').join('')+'</div>':'<div class="empty-state">Adicione contas fictícias e assinaturas mensais para acompanhar os vencimentos.</div>')+'</section>'}
function calendarView(){let a=account(),date=new Date(),month=new Date(date.getFullYear(),date.getMonth()+calendarOffset,1),key=monthKey(month),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),start=month.getDay(),events=[];for(let r of a.recurring)if(r.active)events.push({day:Math.min(days,r.dueDay),label:r.name,kind:'Conta'});for(let c of a.cards)for(let g of invoiceGroups(a,c))if(g.unpaid>0){let due=invoiceDueDate(c,g.key);if(monthKey(due)===key)events.push({day:due.getDate(),label:c.bank+' · '+money(g.unpaid),kind:'Fatura'})}let cells=Array.from({length:start},()=>'<div class="calendar-empty"></div>').concat(Array.from({length:days},(_,i)=>{let day=i+1,list=events.filter(e=>e.day===day);return '<div class="calendar-day"><strong>'+day+'</strong>'+list.map(e=>'<span title="'+escapeHtml(e.kind+' · '+e.label)+'">'+escapeHtml(e.kind+' · '+e.label)+'</span>').join('')+'</div>'}));return '<section class="panel panel-pad"><div class="panel-head"><h2>'+new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month)+'</h2><div class="row-actions"><button class="secondary-button" data-action="calendar-prev">←</button><button class="secondary-button" data-action="calendar-today">Hoje</button><button class="secondary-button" data-action="calendar-next">→</button></div></div><div class="calendar-grid">'+['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>'<span class="calendar-weekday">'+d+'</span>').join('')+cells.join('')+'</div></section>'}
function goalsPage(){let a=account(),total=a.goals.reduce((s,g)=>s+g.saved,0);let body=planningTab==='budgets'?budgetsView():planningTab==='recurring'?recurringView():planningTab==='calendar'?calendarView():'<div class="metric-row"><div class="panel metric-card"><span>Reservado em metas</span><strong>'+money(total)+'</strong><small>Separado do saldo disponível</small></div><div class="panel metric-card"><span>Metas ativas</span><strong>'+a.goals.length+'</strong></div><div class="panel metric-card"><span>Patrimônio simulado</span><strong>'+money(a.balance+total)+'</strong></div></div><button class="primary-button planning-add-goal" data-action="new-goal">＋ Nova meta</button>'+goalCards();return pageHeader('PLANEJE SEU FLUXO','Planejamento.','Orçamentos, vencimentos e metas em um lugar.')+planningTabs()+body+'<section class="panel panel-pad backup-panel"><div class="panel-head"><h2>Dados fictícios</h2></div><p>Salve uma cópia do perfil para importar em outro navegador ou recomece esta demonstração.</p><div class="row-actions"><button class="secondary-button" data-action="export-data">Exportar JSON</button><button class="secondary-button" data-action="import-data">Importar JSON</button><button class="quiet-button" data-action="reset-data">Reiniciar perfil</button></div></section>'}
function simulate(principal,monthly,annual,years){let months=Math.round(years*12),rate=Math.pow(1+annual/100,1/12)-1,amount=principal,values=[];for(let i=1;i<=months;i++){amount=amount*(1+rate)+monthly;if(i%12===0||i===months)values.push(amount)}return{final:amount,invested:principal+monthly*months,gain:amount-(principal+monthly*months),values}}
function investmentsPage(){return pageHeader('EXPLORE CENÁRIOS','Simulador de investimentos.','Veja uma projeção matemática, sem aplicação financeira real.')+'<div class="sim-layout"><form id="sim-form" class="panel panel-pad"><div class="panel-head"><h2>Monte um cenário</h2></div><label class="field">Valor inicial fictício<input id="sim-principal" type="number" min="0" max="100000000" step="0.01" value="1000"></label><br><label class="field">Aporte mensal fictício<input id="sim-monthly" type="number" min="0" max="1000000" step="0.01" value="250"></label><br><label class="field">Taxa anual hipotética (%)<input id="sim-rate" type="number" min="0" max="50" step="0.1" value="8"></label><br><label class="field">Prazo (anos)<input id="sim-years" type="number" min="1" max="40" step="1" value="5"></label><p class="field-hint">Aporte considerado ao fim de cada mês. Resultado nominal, sem impostos, taxas ou inflação.</p></form><div id="sim-output" class="panel sim-result"></div></div><div class="callout" style="margin-top:16px">O cálculo é apenas educativo e hipotético. Taxas futuras variam; esta tela não recomenda investimentos nem executa aplicações.</div>'}
function renderSimulation(){let p=Math.max(0,Number($('sim-principal')?.value)||0),m=Math.max(0,Number($('sim-monthly')?.value)||0),r=Math.min(50,Math.max(0,Number($('sim-rate')?.value)||0)),y=Math.min(40,Math.max(1,Number($('sim-years')?.value)||1)),result=simulate(p,m,r,y),maximum=Math.max(1,...result.values);$('sim-output').innerHTML='<p class="eyebrow">PROJEÇÃO FICTÍCIA</p><span class="balance-caption">Valor projetado ao final de '+y+' anos</span><div class="result-amount">'+money(result.final)+'</div><p>Com taxa hipotética constante de '+r.toLocaleString('pt-BR')+'% ao ano.</p><div class="sim-bars" aria-label="Crescimento projetado por ano">'+result.values.map(v=>'<span style="height:'+Math.max(3,Math.round(v/maximum*100))+'%" title="'+money(v)+'"></span>').join('')+'</div><div class="sim-breakdown"><div><span>Total aportado</span><strong>'+money(result.invested)+'</strong></div><div><span>Rendimento hipotético</span><strong>'+money(result.gain)+'</strong></div><div><span>Valor final</span><strong>'+money(result.final)+'</strong></div></div>'}
function updateNotificationCount(){let n=account()?.notifications.filter(x=>!x.read).length||0;let badge=$('notification-count');badge.textContent=n>9?'9+':String(n);badge.classList.toggle('show',n>0)}
function render(){let a=account();if(!a)return;document.documentElement.dataset.theme=data.theme||'dark';$('theme-top').textContent=data.theme==='dark'?'☼':'☾';$('theme-side').textContent=$('theme-top').textContent;$('avatar').textContent=a.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();$('profile-name').textContent=a.name;let titles={dashboard:'Visão geral',transactions:'Extrato',cards:'Cartões',goals:'Planejamento',investments:'Simulador'};$('breadcrumb').textContent=titles[view]||'Visão geral';document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('main-content').innerHTML=({dashboard,transactions:transactionsPage,cards:cardsPage,goals:goalsPage,investments:investmentsPage}[view]||dashboard)();if(view==='investments')renderSimulation();updateNotificationCount()}
function navigate(name){view=name;txFilter='all';txSearch='';txMonth='all';txCard='all';$('popover-root').innerHTML='';render();window.scrollTo(0,0)}
function modal(title,body,actionLabel,formName){$('modal-root').innerHTML='<div class="modal-scrim"><div class="modal" role="dialog" aria-modal="true" aria-label="'+escapeHtml(title)+'"><div class="modal-head"><h2>'+escapeHtml(title)+'</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fechar">×</button></div><form data-form="'+formName+'">'+body+'<div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">Cancelar</button><button type="submit" class="primary-button">'+actionLabel+'</button></div></form></div></div>';let field=$('modal-root').querySelector('input,select');field?.focus()}
function closeModal(){$('modal-root').innerHTML=''}
function amountField(label='Valor fictício'){return '<label class="field">'+label+'<input name="amount" type="number" min="0.01" max="1000000" step="0.01" placeholder="0,00" required></label>'}
function recipientOptions(){return others().map(a=>'<option value="'+escapeHtml(a.id)+'">'+escapeHtml(a.name)+' · '+escapeHtml(a.bank||'FlowBank')+'</option>').join('')+'<option value="external">Outra conta fictícia</option>'}
function bankOptions(selected){return BANKS.map(bank=>'<option value="'+escapeHtml(bank)+'" '+(bank===selected?'selected':'')+'>'+escapeHtml(bank)+'</option>').join('')}
function openOperation(type){if(type==='transfer'||type==='pix'){let isPix=type==='pix',first=others()[0],selectedBank=first?.bank||'FlowBank';modal(isPix?'Fazer Pix fictício':'Transferir entre contas','<p class="modal-intro">Escolha um perfil local ou uma conta fictícia externa. Nenhuma operação financeira real será realizada.</p><label class="field">Banco de destino<select name="bank" id="operation-bank" required>'+bankOptions(selectedBank)+'</select></label><label class="field">Destinatário<select name="recipient" id="operation-recipient" required>'+recipientOptions()+'</select></label><label class="field" id="external-recipient" hidden>Identificador fictício<input name="external" id="external-name" maxlength="35" placeholder="'+(isPix?'Ex.: pessoa@flow.test':'Ex.: pessoa.demo')+'"></label>'+amountField()+'<label class="field">Descrição<input name="description" maxlength="60" placeholder="Ex.: dividir a conta"></label><div class="callout modal-note">'+(isPix?'Use apenas identificadores de demonstração terminados em @flow.test.':'Bancos e destinatários desta lista são apenas exemplos locais.')+'</div>',isPix?'Simular Pix':'Simular transferência',type);return}if(type==='boleto'){modal('Pagar boleto fictício','<p class="modal-intro">Use um código de demonstração no formato FLOW-2026-001. Códigos bancários reais não são aceitos.</p><label class="field">Código fictício<input name="code" placeholder="FLOW-2026-001" pattern="FLOW-[0-9]{4}-[0-9]{3,6}" required></label>'+amountField()+'<label class="field">Descrição<input name="description" maxlength="60" placeholder="Ex.: serviços"></label>','Simular pagamento','boleto');return}if(type==='receive'){modal('Simular recebimento','<p class="modal-intro">Adicione uma entrada fictícia para testar saldo, extrato e gráficos.</p>'+amountField()+'<label class="field">Origem<input name="description" maxlength="60" placeholder="Ex.: projeto freelance" required></label>','Registrar entrada','receive')}}
function openLimit(id){let a=account(),c=a.cards.find(c=>c.id===id);if(!c)return;let used=cardOutstanding(a,id);modal('Limite · '+c.bank,'<p class="modal-intro">O limite é ocupado por compras ainda não pagas.</p><label class="field">Novo limite (R$)<input name="limit" type="number" min="'+Math.ceil(used)+'" max="100000" step="1" value="'+c.limit+'" required></label><input type="hidden" name="cardId" value="'+escapeHtml(id)+'"><p class="field-hint">Faturas em aberto: '+money(used)+'. O limite não pode ser menor que isso.</p>','Salvar limite','limit')}
function openCardColor(id){let a=account(),c=a.cards.find(c=>c.id===id);if(!c)return;modal('Cor · '+c.bank,'<p class="modal-intro">Escolha qualquer cor. A prévia ajusta o contraste dos números automaticamente.</p><div class="card-preview">'+cardFace(a,c)+'</div><label class="field">Cor do cartão<input name="color" id="card-color-input" type="color" value="'+escapeHtml(c.color)+'"></label><input type="hidden" name="cardId" value="'+escapeHtml(id)+'"><div class="color-swatches" aria-label="Cores sugeridas">'+['#2762af','#8e4eb7','#28847d','#ed9b54','#e7d4a5','#1d2236','#e4667f','#d7e7ec'].map(color=>'<button type="button" data-color-swatch="'+color+'" style="background:'+color+'" aria-label="Escolher cor '+color+'"></button>').join('')+'</div>','Salvar cor','card-color')}
function openAddCard(){let a=account();if(a.cards.length>=12)return toast('Limite de 12 cartões fictícios por perfil.');let preview={bank:'Seu novo banco',color:'#2762af',last4:'0000'};modal('Adicionar cartão fictício','<p class="modal-intro">Cadastre um banco de demonstração e acompanhe compras e faturas separadamente.</p><div class="card-preview">'+cardFace(a,preview)+'</div><label class="field">Nome do banco fictício<input name="bank" id="new-card-bank" list="bank-suggestions" maxlength="30" placeholder="Ex.: Aurora Digital" required></label><datalist id="bank-suggestions">'+BANKS.map(bank=>'<option value="'+escapeHtml(bank)+'"></option>').join('')+'</datalist><label class="field">Cor do cartão<input name="color" id="card-color-input" type="color" value="#2762af"></label><label class="field">Limite fictício (R$)<input name="limit" type="number" min="1" max="100000" step="1" value="3000" required></label><div class="form-grid"><label class="field">Fechamento (dia)<input name="closingDay" type="number" min="1" max="28" value="5" required></label><label class="field">Vencimento (dia)<input name="dueDay" type="number" min="1" max="28" value="12" required></label></div>','Adicionar cartão','add-card')}
function openCardExpense(id){let a=account(),c=a.cards.find(c=>c.id===id);if(!c)return;if(c.blocked)return toast('Desbloqueie este cartão para registrar uma compra.');let remaining=c.limit-cardOutstanding(a,id);modal('Nova compra · '+c.bank,'<p class="modal-intro">A compra ocupa o limite agora. O saldo será descontado somente ao pagar a fatura.</p><label class="field">Estabelecimento fictício<input name="merchant" maxlength="50" placeholder="Ex.: Mercado da esquina" required></label><label class="field">Categoria<select name="category">'+CATEGORIES.map(x=>'<option>'+x+'</option>').join('')+'</select></label>'+amountField('Valor total da compra')+'<label class="field">Parcelas<select name="installments">'+Array.from({length:12},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'×'+(i?' sem juros':' à vista')+'</option>').join('')+'</select></label><input type="hidden" name="cardId" value="'+escapeHtml(id)+'"><p class="field-hint">Limite restante: '+money(Math.max(0,remaining))+'.</p>','Registrar compra','card-expense')}
function openCardSettings(id){let c=account().cards.find(c=>c.id===id);if(!c)return;modal('Datas da fatura · '+c.bank,'<p class="modal-intro">As novas compras usarão estas datas. Faturas já criadas mantêm o mês original.</p><div class="form-grid"><label class="field">Dia de fechamento<input name="closingDay" type="number" min="1" max="28" value="'+c.closingDay+'" required></label><label class="field">Dia de vencimento<input name="dueDay" type="number" min="1" max="28" value="'+c.dueDay+'" required></label></div><input type="hidden" name="cardId" value="'+escapeHtml(id)+'">','Salvar datas','card-settings')}
function openPayInvoice(id,key){let a=account(),c=a.cards.find(c=>c.id===id),group=c&&invoiceGroups(a,c).find(g=>g.key===key);if(!group||group.unpaid<=0)return toast('Fatura não encontrada.');modal('Pagar fatura · '+c.bank,'<p class="modal-intro">Fatura com vencimento em '+dateText(invoiceDueDate(c,key))+'.</p><div class="invoice-pay-amount">'+money(group.unpaid)+'</div><p class="field-hint">O pagamento fictício descontará este valor do saldo disponível.</p><input type="hidden" name="cardId" value="'+escapeHtml(id)+'"><input type="hidden" name="invoiceKey" value="'+escapeHtml(key)+'">','Pagar fatura','pay-invoice')}
function openNewGoal(){modal('Criar nova meta','<p class="modal-intro">Defina um objetivo fictício para acompanhar no painel.</p><label class="field">Nome da meta<input name="name" maxlength="40" placeholder="Ex.: Novo notebook" required></label><label class="field">Valor alvo (R$)<input name="target" type="number" min="1" max="100000000" step="0.01" required></label>','Criar meta','new-goal')}
function openGoalFunds(id,withdraw=false){let g=account().goals.find(x=>x.id===id);if(!g)return;modal(withdraw?'Retirar da meta':'Adicionar à meta','<p class="modal-intro">'+escapeHtml(g.name)+' · reservado: '+money(g.saved)+'</p>'+amountField(withdraw?'Valor a retirar':'Valor a reservar')+'<input name="goalId" type="hidden" value="'+escapeHtml(id)+'">',withdraw?'Retirar valor':'Reservar valor',withdraw?'withdraw-goal':'fund-goal')}
function openBudget(category=''){let b=account().budgets.find(x=>x.category===category);modal(b?'Editar orçamento':'Definir orçamento','<label class="field">Categoria<select name="category" '+(b?'disabled':'')+'>'+CATEGORIES.map(c=>'<option '+(c===category?'selected':'')+'>'+c+'</option>').join('')+'</select></label>'+(b?'<input type="hidden" name="category" value="'+escapeHtml(category)+'">':'')+'<label class="field">Limite mensal (R$)<input name="limit" type="number" min="1" max="1000000" step="0.01" value="'+(b?b.limit:'')+'" required></label>','Salvar orçamento','budget')}
function openRecurring(id=''){let r=account().recurring.find(x=>x.id===id);modal(r?'Editar recorrência':'Adicionar recorrência','<input type="hidden" name="recurringId" value="'+escapeHtml(id)+'"><label class="field">Nome fictício<input name="name" maxlength="50" value="'+escapeHtml(r?.name||'')+'" required></label><label class="field">Categoria<select name="category">'+CATEGORIES.map(c=>'<option '+(r?.category===c?'selected':'')+'>'+c+'</option>').join('')+'</select></label>'+amountField('Valor mensal fictício').replace('placeholder="0,00"','value="'+(r?.amount||'')+'"')+'<label class="field">Dia do vencimento<input name="dueDay" type="number" min="1" max="28" value="'+(r?.dueDay||10)+'" required></label>','Salvar recorrência','recurring')}
function openEditTx(id){let t=account().transactions.find(x=>x.id===id);if(!t)return;modal('Editar movimentação','<p class="modal-intro">'+escapeHtml(t.description)+' · '+money(Math.abs(t.amount))+'</p><input type="hidden" name="txId" value="'+escapeHtml(id)+'"><label class="field">Categoria<select name="category">'+[...new Set([...CATEGORIES,t.category])].map(c=>'<option '+(t.category===c?'selected':'')+'>'+escapeHtml(c)+'</option>').join('')+'</select></label><label class="field">Nota pessoal<textarea name="note" maxlength="180" rows="3" placeholder="Adicione um contexto para este gasto">'+escapeHtml(t.note||'')+'</textarea></label>','Salvar alterações','edit-tx')}
function openImport(){modal('Importar dados fictícios','<p class="modal-intro">O arquivo cria um novo perfil local com uma nova senha. Use apenas um backup JSON do FlowBank.</p><label class="field">Arquivo JSON<input name="file" type="file" accept=".json,application/json" required></label><label class="field">Nova senha local<input name="password" type="password" minlength="12" maxlength="128" required></label><label class="field">Confirmar senha<input name="confirm" type="password" minlength="12" maxlength="128" required></label>','Importar perfil','import-data')}
function openReset(){modal('Reiniciar perfil fictício','<p class="modal-intro">Isso apagará movimentações, cartões adicionais, orçamentos, recorrências e metas deste perfil local. A senha será preservada.</p><label class="field">Digite REINICIAR para confirmar<input name="confirm" autocomplete="off" required></label>','Reiniciar perfil','reset-data')}
async function importData(form){let fd=new FormData(form),file=fd.get('file'),password=String(fd.get('password')||''),confirm=String(fd.get('confirm')||'');if(!passwordValid(password,confirm))return;if(!file||file.size>2000000)return toast('Escolha um JSON de até 2 MB.');let raw;try{raw=JSON.parse(await file.text())}catch{return toast('Arquivo JSON inválido.')}let source=raw?.flowbankBackup===1&&raw.profile;if(!source||typeof source!=='object'||typeof source.name!=='string'||typeof source.handle!=='string'||!Array.isArray(source.cards)||!Array.isArray(source.transactions)||source.cards.length<1||source.cards.length>12||source.transactions.length>10000||!Array.isArray(source.goals)||!Array.isArray(source.budgets)||!Array.isArray(source.recurring)||!Array.isArray(source.notifications))return toast('Backup incompatível.');if(data.accounts.length>=30)return toast('Limite de perfis locais alcançado.');let name=source.name.trim().slice(0,60),handle=source.handle.trim().slice(0,30);if(name.length<2||!/^[a-z0-9._-]{3,30}$/i.test(handle)||!Number.isFinite(source.balance)||Math.abs(source.balance)>100000000)return toast('Dados do perfil inválidos.');let duplicate=data.accounts.some(x=>x.handle.toLowerCase()===handle.toLowerCase());if(duplicate){let suffix=1;while(data.accounts.some(x=>x.handle.toLowerCase()===(handle+'-'+suffix).toLowerCase()))suffix++;handle=handle.slice(0,25)+'-'+suffix}let cards=source.cards.map(c=>({id:uid(),bank:String(c.bank||'Banco fictício').slice(0,30),limit:Number(c.limit),blocked:!!c.blocked,color:/^#[0-9a-f]{6}$/i.test(c.color)?c.color:'#2762af',last4:/^\d{4}$/.test(String(c.last4))?String(c.last4):'2048',closingDay:Number(c.closingDay)||5,dueDay:Number(c.dueDay)||12}));if(cards.some(c=>!Number.isFinite(c.limit)||c.limit<1||c.limit>100000||c.closingDay<1||c.closingDay>28||c.dueDay<1||c.dueDay>28))return toast('Cartões inválidos no backup.');let cardMap=new Map(source.cards.map((c,i)=>[c.id,cards[i].id]));let tx=source.transactions.map(t=>({id:uid(),date:String(t.date),amount:Number(t.amount),cashDelta:t.billingMode==='invoice'?0:Number.isFinite(t.cashDelta)?Number(t.cashDelta):Number(t.amount),description:String(t.description||'').slice(0,100),category:String(t.category||'Outros').slice(0,40),method:String(t.method||'Outro').slice(0,30),counterparty:String(t.counterparty||'').slice(0,70),note:String(t.note||'').slice(0,180),cardId:cardMap.get(t.cardId)||undefined,billingMode:t.billingMode==='invoice'?'invoice':t.billingMode==='paid-direct'?'paid-direct':undefined,invoiceKey:/^\d{4}-\d{2}$/.test(t.invoiceKey||'')?t.invoiceKey:undefined,paidAt:t.paidAt?String(t.paidAt):undefined,installmentIndex:Number(t.installmentIndex)||undefined,installments:Number(t.installments)||undefined}));if(tx.some(t=>!Number.isFinite(t.amount)||!Number.isFinite(t.cashDelta)||Math.abs(t.amount)>1000000||Math.abs(t.cashDelta)>1000000||!Number.isFinite(new Date(t.date).getTime())))return toast('Movimentações inválidas no backup.');let a={id:uid(),name,handle,bank:BANKS.includes(source.bank)?source.bank:'FlowBank',demoRecipient:false,pix:handle+'@flow.test',balance:source.balance,cards,transactions:tx,goals:source.goals.slice(0,100).map(g=>({id:uid(),name:String(g.name||'Meta').slice(0,40),target:Number(g.target)||1,saved:Number(g.saved)||0,icon:'◎'})),budgets:source.budgets.slice(0,30).filter(b=>CATEGORIES.includes(b.category)&&Number.isFinite(b.limit)&&b.limit>0).map(b=>({category:b.category,limit:b.limit})),recurring:source.recurring.slice(0,100).filter(r=>Number.isFinite(r.amount)&&r.amount>0&&Number.isInteger(r.dueDay)&&r.dueDay>=1&&r.dueDay<=28).map(r=>({id:uid(),name:String(r.name||'Conta').slice(0,50),amount:r.amount,category:CATEGORIES.includes(r.category)?r.category:'Outros',dueDay:r.dueDay,active:!!r.active,lastPaidKey:String(r.lastPaidKey||'')})),notifications:[]};await setPassword(a,password);data.accounts.push(a);data.activeId=a.id;unlockedId=a.id;save();closeModal();showAuth();toast('Perfil importado com nova senha local')}
function exportData(){let a=account(),copy=JSON.parse(JSON.stringify(a));delete copy.auth;delete copy.id;delete copy.demoRecipient;let blob=new Blob([JSON.stringify({flowbankBackup:1,exportedAt:new Date().toISOString(),profile:copy},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='flowbank-'+a.handle+'-'+monthKey(new Date())+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup fictício exportado')}
function formValue(fd,name){return safeNumber(fd.get(name))}
function processForm(form){let fd=new FormData(form),kind=form.dataset.form,a=account(),amount=formValue(fd,'amount');if(kind==='transfer'||kind==='pix'){let bank=String(fd.get('bank')||''),recipient=data.accounts.find(x=>x.id===fd.get('recipient')),external=fd.get('recipient')==='external',alias=String(fd.get('external')||'').trim(),method=kind==='pix'?'Pix':'Transferência',description=String(fd.get('description')||'').trim();if(!BANKS.includes(bank))return toast('Escolha um banco fictício válido.');if(!validAmount(amount))return toast('Informe um valor fictício válido.');if(amount>a.balance)return toast('Saldo fictício insuficiente.');if(external){let valid=kind==='pix'?/^[a-z0-9._-]{3,25}@flow\.test$/i.test(alias):/^[a-z0-9._-]{3,35}$/i.test(alias);if(!valid)return toast(kind==='pix'?'Use uma chave fictícia terminada em @flow.test.':'Use um identificador fictício de 3 a 35 caracteres.')}else if(!recipient||recipient.id===a.id||recipient.bank!==bank)return toast('Confira o destinatário e o banco de destino.');let name=external?alias:recipient.name;post(a,{amount:-amount,description:(kind==='pix'?'Pix para ':'Transferência para ')+name+' · '+bank+(description?' · '+description:''),category:'Transferências',method,counterparty:name});if(recipient&&!external)post(recipient,{amount,description:(kind==='pix'?'Pix de ':'Transferência de ')+a.name+(description?' · '+description:''),category:'Receitas',method,counterparty:a.name});commit();closeModal();return toast(method+' fictício concluído')}if(kind==='boleto'){let code=String(fd.get('code')||'').trim().toUpperCase();if(!/^FLOW-\d{4}-\d{3,6}$/.test(code))return toast('Use um código fictício FLOW-AAAA-NNN.');if(!validAmount(amount))return toast('Informe um valor fictício válido.');if(amount>a.balance)return toast('Saldo fictício insuficiente.');let description=String(fd.get('description')||'').trim();post(a,{amount:-amount,description:'Boleto '+code+(description?' · '+description:''),category:'Contas',method:'Boleto',counterparty:''});commit();closeModal();return toast('Boleto fictício pago')}if(kind==='receive'){if(!validAmount(amount))return toast('Informe um valor fictício válido.');let description=String(fd.get('description')||'').trim();if(!description)return toast('Informe uma origem fictícia.');post(a,{amount,description,category:'Receitas',method:'Recebimento',counterparty:''});commit();closeModal();return toast('Recebimento fictício registrado')}if(kind==='add-card'){let bank=String(fd.get('bank')||'').trim(),color=String(fd.get('color')||''),limit=formValue(fd,'limit'),closingDay=Number(fd.get('closingDay')),dueDay=Number(fd.get('dueDay'));if(a.cards.length>=12)return toast('Limite de 12 cartões fictícios por perfil.');if(bank.length<2||bank.length>30||!/^#[0-9a-f]{6}$/i.test(color)||!Number.isFinite(limit)||limit<1||limit>100000||!Number.isInteger(closingDay)||closingDay<1||closingDay>28||!Number.isInteger(dueDay)||dueDay<1||dueDay>28)return toast('Confira os dados do cartão fictício.');a.cards.push({id:uid(),bank,color,limit,closingDay,dueDay,blocked:false,last4:String(Math.floor(1000+Math.random()*9000))});notify(a,'Cartão fictício de '+bank+' adicionado.');commit();closeModal();return toast('Cartão adicionado')}if(kind==='card-expense'){let c=a.cards.find(c=>c.id===fd.get('cardId')),merchant=String(fd.get('merchant')||'').trim(),category=String(fd.get('category')||'Outros'),installments=Number(fd.get('installments'));if(!c||c.blocked)return toast('Cartão indisponível.');if(merchant.length<2||merchant.length>50||!CATEGORIES.includes(category)||!validAmount(amount)||!Number.isInteger(installments)||installments<1||installments>12)return toast('Confira os dados da compra.');if(amount>c.limit-cardOutstanding(a,c.id)+.001)return toast('Valor acima do limite disponível.');let now=new Date(),base=invoiceKeyFor(now,c.closingDay),before=categorySpend(a,category,monthKey(now)),cents=Math.round(amount*100),baseCents=Math.floor(cents/installments),remainder=cents-baseCents*installments,group=uid();for(let i=0;i<installments;i++){let part=(baseCents+(i<remainder?1:0))/100;a.transactions.unshift({id:uid(),date:now.toISOString(),amount:-part,cashDelta:0,description:merchant,category,method:'Cartão',counterparty:merchant,cardId:c.id,billingMode:'invoice',invoiceKey:addMonthsKey(base,i),purchaseGroupId:group,installmentIndex:i+1,installments})}checkBudget(a,category,before,categorySpend(a,category,monthKey(now)));notify(a,'Compra fictícia de '+money(amount)+' em '+c.bank+(installments>1?' · '+installments+' parcelas':''));commit();closeModal();return toast('Compra registrada em '+c.bank)}if(kind==='pay-invoice'){let c=a.cards.find(c=>c.id===fd.get('cardId')),key=String(fd.get('invoiceKey')||''),group=c&&invoiceGroups(a,c).find(g=>g.key===key);if(!group||group.unpaid<=0)return toast('Fatura não encontrada.');let payable=Math.round(group.unpaid*100)/100;if(payable>a.balance)return toast('Saldo fictício insuficiente para pagar a fatura.');let now=new Date().toISOString();group.items.filter(t=>!t.paidAt).forEach(t=>t.paidAt=now);post(a,{amount:-payable,cashDelta:-payable,description:'Fatura '+c.bank+' · '+key,category:'Faturas',method:'Fatura',cardId:c.id,invoiceKey:key,counterparty:c.bank});commit();closeModal();return toast('Fatura fictícia paga')}if(kind==='card-settings'){let c=a.cards.find(c=>c.id===fd.get('cardId')),closingDay=Number(fd.get('closingDay')),dueDay=Number(fd.get('dueDay'));if(!c||!Number.isInteger(closingDay)||closingDay<1||closingDay>28||!Number.isInteger(dueDay)||dueDay<1||dueDay>28)return toast('Escolha dias entre 1 e 28.');c.closingDay=closingDay;c.dueDay=dueDay;notify(a,'Datas da fatura de '+c.bank+' atualizadas.');commit();closeModal();return toast('Datas atualizadas')}if(kind==='limit'){let c=a.cards.find(c=>c.id===fd.get('cardId')),limit=formValue(fd,'limit');if(!c||!Number.isFinite(limit)||limit<Math.round(cardOutstanding(a,c.id)*100)/100||limit>100000)return toast('O limite deve cobrir as faturas em aberto.');c.limit=limit;notify(a,'Limite de '+c.bank+' ajustado para '+money(limit));commit();closeModal();return toast('Limite atualizado')}if(kind==='card-color'){let c=a.cards.find(c=>c.id===fd.get('cardId')),color=String(fd.get('color')||'');if(!c)return toast('Cartão não encontrado.');if(!/^#[0-9a-f]{6}$/i.test(color))return toast('Escolha uma cor válida.');c.color=color;notify(a,'Cor do cartão '+c.bank+' atualizada.');commit();closeModal();return toast('Cartão personalizado')}if(kind==='budget'){let category=String(fd.get('category')||''),limit=formValue(fd,'limit');if(!CATEGORIES.includes(category)||!Number.isFinite(limit)||limit<1||limit>1000000)return toast('Informe categoria e limite válidos.');let b=a.budgets.find(x=>x.category===category);if(b)b.limit=limit;else a.budgets.push({category,limit});notify(a,'Orçamento de '+category+' definido em '+money(limit));commit();closeModal();return toast('Orçamento salvo')}if(kind==='recurring'){let id=String(fd.get('recurringId')||''),name=String(fd.get('name')||'').trim(),category=String(fd.get('category')||''),dueDay=Number(fd.get('dueDay'));if(name.length<2||name.length>50||!CATEGORIES.includes(category)||!validAmount(amount)||!Number.isInteger(dueDay)||dueDay<1||dueDay>28)return toast('Confira os dados da recorrência.');let r=a.recurring.find(x=>x.id===id);if(r)Object.assign(r,{name,category,amount,dueDay});else a.recurring.push({id:uid(),name,category,amount,dueDay,active:true,lastPaidKey:''});commit();closeModal();return toast('Recorrência salva')}if(kind==='edit-tx'){let t=a.transactions.find(x=>x.id===fd.get('txId')),category=String(fd.get('category')||''),note=String(fd.get('note')||'').trim();if(!t||![...CATEGORIES,t.category].includes(category)||note.length>180)return toast('Confira categoria e nota.');t.category=category;t.note=note;commit();closeModal();return toast('Movimentação atualizada')}if(kind==='reset-data'){if(fd.get('confirm')!=='REINICIAR')return toast('Digite REINICIAR para confirmar.');let first=a.cards[0];a.balance=0;a.transactions=[];a.goals=[];a.budgets=[];a.recurring=[];a.cards=[{...first,blocked:false}];a.notifications=[];notify(a,'Perfil fictício reiniciado.');commit();closeModal();return toast('Perfil reiniciado')}if(kind==='new-goal'){let name=String(fd.get('name')||'').trim(),target=formValue(fd,'target');if(!name||!Number.isFinite(target)||target<=0||target>100000000)return toast('Preencha nome e valor alvo válidos.');a.goals.push({id:uid(),name,target,saved:0,icon:'◎'});notify(a,'Nova meta criada: '+name);commit();closeModal();return toast('Meta criada')}if(kind==='fund-goal'||kind==='withdraw-goal'){let goal=a.goals.find(g=>g.id===fd.get('goalId'));if(!goal)return toast('Meta não encontrada.');if(!validAmount(amount))return toast('Informe um valor fictício válido.');if(kind==='fund-goal'){if(amount>a.balance)return toast('Saldo fictício insuficiente.');goal.saved=safeNumber(goal.saved+amount);post(a,{amount:-amount,description:'Reserva para '+goal.name,category:'Meta',method:'Meta',counterparty:''})}else{if(amount>goal.saved)return toast('Valor maior que o reservado.');goal.saved=safeNumber(goal.saved-amount);post(a,{amount,description:'Retirada de '+goal.name,category:'Meta',method:'Meta',counterparty:''})}commit();closeModal();return toast('Meta atualizada')}}
function toggleTheme(){data.theme=data.theme==='dark'?'light':'dark';save();render()}
function notifications(){let a=account();$('popover-root').innerHTML='<div class="notifications-popover"><div class="popover-header"><strong>Notificações</strong><button class="quiet-button" data-action="read-notifications">Marcar como lidas</button></div>'+(a.notifications.length?a.notifications.map(n=>'<div class="notification-item '+(n.read?'':'unread')+'"><strong>'+escapeHtml(n.text)+'</strong><span>'+dateText(n.date)+'</span></div>').join(''):'<div class="empty-state">Tudo em dia por aqui.</div>')+'</div>'}
function profileMenu(){$('popover-root').innerHTML='<div class="profile-popover"><button data-action="switch-profile">Trocar perfil local</button><button data-action="theme">Alternar tema</button><button data-action="logout">Sair da demonstração</button></div>'}
document.addEventListener('click',event=>{let el=event.target.closest('button[data-action],button[data-view],button[data-period],button[data-color-swatch],button[data-planning-tab]');if(!el)return;if(el.dataset.view){navigate(el.dataset.view);return}if(el.dataset.period){chartPeriod=Number(el.dataset.period);render();return}if(el.dataset.planningTab){planningTab=el.dataset.planningTab;render();return}if(el.dataset.colorSwatch){let input=$('card-color-input');if(input){input.value=el.dataset.colorSwatch;updateCardPreview(input.value)}return}let action=el.dataset.action,id=el.dataset.id,a=account();if(['transfer','pix','boleto','receive'].includes(action))return openOperation(action);if(action==='statement')return navigate('transactions');if(action==='cards')return navigate('cards');if(action==='add-card')return openAddCard();if(action==='card-expense')return openCardExpense(id);if(action==='card-invoices'){navigate('cards');$('invoice-section')?.scrollIntoView({behavior:'smooth'});return}if(action==='pay-invoice')return openPayInvoice(id,el.dataset.key);if(action==='card-settings')return openCardSettings(id);if(action==='toggle-card'){let c=a.cards.find(c=>c.id===id);if(!c)return;c.blocked=!c.blocked;notify(a,(c.blocked?'Cartão bloqueado: ':'Cartão desbloqueado: ')+c.bank);commit();return toast(c.blocked?'Cartão bloqueado':'Cartão desbloqueado')}if(action==='limit')return openLimit(id);if(action==='card-color')return openCardColor(id);if(action==='budget-edit')return openBudget(id);if(action==='budget-remove'){a.budgets=a.budgets.filter(b=>b.category!==id);commit();return toast('Orçamento removido')}if(action==='recurring-edit')return openRecurring(id);if(action==='recurring-toggle'){let r=a.recurring.find(x=>x.id===id);if(!r)return;r.active=!r.active;commit();return toast(r.active?'Recorrência ativada':'Recorrência pausada')}if(action==='recurring-remove'){a.recurring=a.recurring.filter(x=>x.id!==id);commit();return toast('Recorrência removida')}if(action==='recurring-pay'){let r=a.recurring.find(x=>x.id===id),key=monthKey(new Date());if(!r||!r.active||r.lastPaidKey===key)return;if(r.amount>a.balance)return toast('Saldo fictício insuficiente.');post(a,{amount:-r.amount,description:r.name,category:r.category,method:'Recorrência',counterparty:''});r.lastPaidKey=key;commit();return toast('Conta fictícia paga')}if(action==='calendar-prev'){calendarOffset--;render();return}if(action==='calendar-next'){calendarOffset++;render();return}if(action==='calendar-today'){calendarOffset=0;render();return}if(action==='edit-tx')return openEditTx(id);if(action==='export-data')return exportData();if(action==='import-data')return openImport();if(action==='reset-data')return openReset();if(action==='new-goal')return openNewGoal();if(action==='add-goal-funds')return openGoalFunds(id);if(action==='goal-menu')return openGoalFunds(id,true);if(action==='close-modal')return closeModal();if(action==='theme'){toggleTheme();$('popover-root').innerHTML='';return}if(action==='logout'||action==='switch-profile')return logout();if(action==='read-notifications'){a.notifications.forEach(n=>n.read=true);save();notifications();updateNotificationCount()}});
function updateCardPreview(color){let card=$('modal-root').querySelector('.virtual-card');if(card){card.style.setProperty('--card-color',color);card.style.setProperty('--card-ink',cardInk(color))}}
async function authSubmit(button,task){button.disabled=true;let previous=button.innerHTML;button.textContent='Verificando...';try{await task()}catch{toast('Não foi possível processar a senha neste navegador.')}finally{button.disabled=false;button.innerHTML=previous}}
document.addEventListener('submit',event=>{if(event.target.id==='login-form'){event.preventDefault();authSubmit($('login-submit'),()=>login($('login-profile').value,$('login-password').value,$('login-confirm').value));return}if(event.target.id==='register-form'){event.preventDefault();authSubmit($('register-submit'),()=>register($('register-name').value,$('register-handle').value,$('register-bank').value,$('register-password').value,$('register-confirm').value));return}if(event.target.dataset.form){event.preventDefault();if(event.target.dataset.form==='import-data'){let button=event.target.querySelector('[type=submit]');authSubmit(button,()=>importData(event.target));return}processForm(event.target)}});
document.addEventListener('click',event=>{let button=event.target.closest('[data-password-toggle]');if(!button)return;let input=$(button.dataset.passwordToggle);input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Mostrar':'Ocultar';button.setAttribute('aria-label',(input.type==='password'?'Mostrar':'Ocultar')+' senha')});
document.addEventListener('input',event=>{if(event.target.id==='tx-search'){txSearch=event.target.value;$('transaction-rows').innerHTML=txRows(filteredTransactions())}if(event.target.id==='card-color-input')updateCardPreview(event.target.value);if(event.target.id==='new-card-bank'){let label=$('modal-root').querySelector('.card-bottom span:last-child');if(label)label.textContent=(event.target.value.trim()||'Seu novo banco')+' · DEMO'}if(event.target.closest('#sim-form'))renderSimulation()});
document.addEventListener('change',event=>{if(event.target.id==='tx-type'){txFilter=event.target.value;$('transaction-rows').innerHTML=txRows(filteredTransactions())}if(event.target.id==='tx-month'){txMonth=event.target.value;$('transaction-rows').innerHTML=txRows(filteredTransactions())}if(event.target.id==='tx-card'){txCard=event.target.value;$('transaction-rows').innerHTML=txRows(filteredTransactions())}if(event.target.id==='login-profile'){syncLoginPasswordMode();$('login-password').value='';$('login-confirm').value=''}if(event.target.id==='operation-recipient'){let external=event.target.value==='external',label=$('external-recipient'),input=$('external-name');label.hidden=!external;input.required=external;let a=data.accounts.find(x=>x.id===event.target.value);if(a)$('operation-bank').value=a.bank}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();$('popover-root').innerHTML=''}});
$('login-tab').onclick=()=>setAuthTab('login');$('register-tab').onclick=()=>setAuthTab('register');
$('theme-top').onclick=toggleTheme;$('theme-side').onclick=toggleTheme;
$('logout-side').onclick=logout;$('notifications-button').onclick=()=>{if($('popover-root').querySelector('.notifications-popover'))$('popover-root').innerHTML='';else notifications()};$('profile-button').onclick=()=>{if($('popover-root').querySelector('.profile-popover'))$('popover-root').innerHTML='';else profileMenu()};
document.documentElement.dataset.theme=data.theme||'dark';
showAuth();
